# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Import and connect already provided — just verify they exist
if 'import sqlite3' not in student_code:
    raise AssertionError('Task 1: Missing "import sqlite3"')
if 'with sqlite3.connect' not in student_code:
    raise AssertionError('Task 1: Missing with statement for connection')

# Task 2: Check execute with create_table_sql
if not any('execute(create_table_sql)' in line for line in lines):
    raise AssertionError('Task 2: Should call cursor.execute(create_table_sql)')

# Task 3: Check execute with insert_sql and tuple
if not any('execute(insert_sql' in line and 'Keyboard' in line for line in lines):
    raise AssertionError("Task 3: Should call cursor.execute(insert_sql, ('Keyboard', 75.00))")

# Task 4: Check executemany
if not any('executemany(insert_sql, more_products)' in line for line in lines):
    raise AssertionError('Task 4: Should call cursor.executemany(insert_sql, more_products)')

# Task 5: Check commit and print
if not any('conn.commit()' in line for line in lines):
    raise AssertionError('Task 5: Should call conn.commit()')
if not any('Products table created' in line for line in lines):
    raise AssertionError('Task 5: Should print the confirmation message')

print('TEST_PASSED')
